body:
${cartesianContainer}
& :where(.openui-bar-chart-container-inner) {
  ${cartesianContainerInner}
}
& :where(.openui-bar-chart-y-axis-container) {
  ${cartesianYAxisContainer}
}
& :where(.openui-bar-chart-main-container) {
  ${cartesianMainContainer}
}
& line:where(.openui-bar-chart-grid line) {
  ${gridLine}
}
& line.openui-grid-zero-line:where(.openui-bar-chart-grid line) {
  ${zeroGridLine}
}
& :where(.openui-bar-chart-y-tick, .openui-bar-chart-x-tick, .openui-bar-chart-x-tick-angled) {
  ${svgTickLabel}
}
& :where(.openui-bar-chart-hover-highlight) {
  fill: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  opacity: 0.04;
  pointer-events: none;
}
& :where(.openui-bar-chart-internal-line) {
  pointer-events: none;
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-bar-chart-bar--animated) {
    transform-box: fill-box;
    transform-origin: center bottom;
    animation: ${grow} 0.6s ease-out both;
  }
  & .openui-bar-chart-bar--negative:where(.openui-bar-chart-bar--animated) {
    transform-origin: center top;
  }
}

position: relative;
width: 100%;
height: auto;
display: flex;
flex-direction: column;
& :where(.openui-horizontal-bar-chart-container-inner-wrapper) {
  width: 100%;
  display: flex;
  flex-direction: row;
  overflow: hidden;
}
& :where(.openui-horizontal-bar-chart-container-inner) {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  flex: 1;
  min-width: 0;
}
& :where(.openui-horizontal-bar-chart-main-container) {
  height: 100%;
  overflow-y: auto;
  &::-webkit-scrollbar {
    display: none;
  }
  scrollbar-width: none;
  ms-overflow-style: none;
}
& :where(.openui-horizontal-bar-chart-x-axis-container) {
  flex-shrink: 0;
  width: 100%;
  box-sizing: border-box;
  border-top: 1px solid var(--openui-border-default, oklch(0.097 0 0 / 0.06));
  padding-top: var(--openui-space-2xs, 4px);
}
& :where(.openui-horizontal-bar-chart-category-label) {
  display: flex;
  align-items: center;
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
  ${svgTickTypography}
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  width: 100%;
  padding-left: var(--openui-space-m, 12px);
  box-sizing: border-box;
}
& :where(.openui-horizontal-bar-chart-x-tick) {
  ${svgTickLabel}
}
& line:where(.openui-horizontal-bar-chart-grid-vertical line) {
  ${gridLine}
}
& :where(.openui-horizontal-bar-chart-internal-line) {
  pointer-events: none;
}
& :where(.openui-horizontal-bar-chart-crosshair) {
  fill: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  opacity: 0.04;
  pointer-events: none;
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-horizontal-bar-chart-bar--animated) {
    transform-box: fill-box;
    transform-origin: left center;
    animation: ${grow} 0.6s ease-out both;
  }
  & .openui-horizontal-bar-chart-bar--negative:where(.openui-horizontal-bar-chart-bar--animated) {
    transform-origin: right center;
  }
}

& {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  position: relative;
}

& :where(.openui-calendar-heatmap-month-label),
& :where(.openui-calendar-heatmap-weekday-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  fill: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}

& :hover:where(.openui-calendar-heatmap-cell) {
  stroke: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
  stroke-width: 1.5;
}

& :where(.openui-calendar-heatmap-cell--ghost) {
  fill-opacity: 0.4;
}

@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-calendar-heatmap-cell--animated) {
    opacity: 0;
    animation: ${cellIn} 0.4s ease-out forwards;
  }
}
&
  [data-openui-highlight-level="0"]
  :not(.openui-calendar-heatmap-cell--level-0):where(.openui-calendar-heatmap-cell) {
  fill-opacity: 0.3;
}

&
  [data-openui-highlight-level="1"]
  :not(.openui-calendar-heatmap-cell--level-1):where(.openui-calendar-heatmap-cell) {
  fill-opacity: 0.3;
}

&
  [data-openui-highlight-level="2"]
  :not(.openui-calendar-heatmap-cell--level-2):where(.openui-calendar-heatmap-cell) {
  fill-opacity: 0.3;
}

&
  [data-openui-highlight-level="3"]
  :not(.openui-calendar-heatmap-cell--level-3):where(.openui-calendar-heatmap-cell) {
  fill-opacity: 0.3;
}

&
  [data-openui-highlight-level="4"]
  :not(.openui-calendar-heatmap-cell--level-4):where(.openui-calendar-heatmap-cell) {
  fill-opacity: 0.3;
}

@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-calendar-heatmap-cell),
  & :where(.openui-calendar-heatmap-legend-swatch-slot) {
    transition:
      fill-opacity 0.2s ease,
      opacity 0.2s ease;
  }
}
& :where(.openui-calendar-heatmap-separator) {
  stroke: var(--openui-border-default, oklch(0.097 0 0 / 0.06));
  stroke-width: 1;
}

& :where(.openui-calendar-heatmap-quarter-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
  white-space: nowrap;
  pointer-events: none;
}

& :where(.openui-calendar-heatmap-legend) {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--openui-space-s, 8px);
  width: 100%;
  padding-top: var(--openui-space-m, 12px);
}
& :where(.openui-calendar-heatmap-legend-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}
& :where(.openui-calendar-heatmap-legend-swatches) {
  display: flex;
  align-items: center;
  gap: var(--openui-space-3xs, 2px);
}
& :where(.openui-calendar-heatmap-legend-swatch-slot) {
  display: inline-flex;
  cursor: pointer;
}
& :where(.openui-calendar-heatmap-legend-swatch) {
  display: block;
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  border-radius: var(--openui-radius-2xs, 2px);
}
& :where(.openui-calendar-heatmap-legend-gradient) {
  position: relative;
  width: 60px;
  height: 12px;
  flex-shrink: 0;
  border-radius: var(--openui-radius-2xs, 2px);
}
& :where(.openui-calendar-heatmap-legend-gradient-hit) {
  position: absolute;
  top: 0;
  height: 100%;
  cursor: pointer;
}

& {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  position: relative;
}

& :where(.openui-funnel-chart-ring) {
  transition:
    d 0.3s ease,
    fill-opacity 0.2s ease;
}

& :where(.openui-funnel-chart-ring--springy) {
  transform-box: fill-box;
  transform-origin: center;
}

& :where(.openui-funnel-chart-ring--bloom-y) {
  transform: scaleY(var(--funnel-ring-scale, 1));
}

& :where(.openui-funnel-chart-ring--bloom-x) {
  transform: scaleX(var(--funnel-ring-scale, 1));
}

& :where(.openui-funnel-chart-stage) {
  transition: filter 0.2s ease;
}

@media print {
  & :where(.openui-funnel-chart-ring),
  & :where(.openui-funnel-chart-stage) {
    transition: none;
  }
}
& :where(.openui-funnel-chart-value) {
  font: var(--openui-text-label-sm, 400 14px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-sm-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  fill: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  font-weight: 600;
  font-variation-settings: normal;
}

& :where(.openui-funnel-chart-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  fill: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}

& :where(.openui-funnel-chart-pct) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  fill: var(--openui-background, oklch(0.97 0 89.876 / 1));
  font-weight: 700;
  font-variation-settings: normal;
}

& :where(.openui-funnel-chart-pct-pill) {
  fill: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
}

@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-funnel-chart-stage--animated) {
    opacity: 0;
    transform-box: fill-box;
    transform-origin: center;
    animation: ${appear} 0.5s ease-out forwards;
  }
}

${centeredContainer}
& :where(.openui-heatmap-chart-x-tick), & :where(.openui-heatmap-chart-y-tick) {
  ${svgTickLabel}
}
& :where(.openui-heatmap-chart-cell),
& :where(.openui-heatmap-chart-cell-label) {
  transition: fill 0.2s ease;
}
@media print {
  & :where(.openui-heatmap-chart-cell),
  & :where(.openui-heatmap-chart-cell-label) {
    transition: none;
  }
}
& :hover:where(.openui-heatmap-chart-cell) {
  stroke: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  stroke-width: 1.5;
}
& :where(.openui-heatmap-chart-cell-label) {
  ${labelTypography}
  pointer-events: none;
  user-select: none;
}
& :where(.openui-heatmap-chart-cell--empty) {
  fill: var(--openui-border-default, oklch(0.097 0 0 / 0.06));
  fill-opacity: 0.35;
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-heatmap-chart-cell--animated),
  & :where(.openui-heatmap-chart-cell-label--animated) {
    opacity: 0;
    animation: ${fadeAppearAnimation} 0.4s ease-out forwards;
  }
}
& :where(.openui-heatmap-chart-color-scale) {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 0 2px;
}
& :where(.openui-heatmap-chart-color-scale-label) {
  ${labelTypography}
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
  white-space: nowrap;
}
& :where(.openui-heatmap-chart-color-scale-ramp) {
  position: relative;
  display: flex;
  flex: 1;
  height: 8px;
  border-radius: 4px;
  overflow: hidden;
}
& :where(.openui-heatmap-chart-color-scale-bucket) {
  flex: 1;
}

&::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  transform: translateX(-50%);
  background: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  opacity: 0.55;
}

${cartesianContainer}
& :where(.openui-line-chart-container-inner) {
  ${cartesianContainerInner}
}
& :where(.openui-line-chart-y-axis-container) {
  ${cartesianYAxisContainer}
}
& :where(.openui-line-chart-main-container) {
  ${cartesianMainContainer}
}
& line:where(.openui-line-chart-grid line) {
  ${gridLine}
}
& line.openui-grid-zero-line:where(.openui-line-chart-grid line) {
  ${zeroGridLine}
}
& :where(.openui-line-chart-y-tick, .openui-line-chart-x-tick, .openui-line-chart-x-tick-angled) {
  ${svgTickLabel}
}
& :where(.openui-line-chart-crosshair-line) {
  ${crosshairLine}
}
& :where(.openui-line-chart-active-dot-outer) {
  ${activeDotOuter}
}
& :where(.openui-line-chart-active-dot-inner) {
  ${activeDotInner}
}
& :where(.openui-line-chart-line) {
  fill: none;
  stroke-width: 2;
}
& :where(.openui-line-chart-dot) {
  stroke: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
  stroke-width: 1;
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-line-chart-line--animated) {
    stroke-dasharray: var(--path-length);
    stroke-dashoffset: var(--path-length);
    animation: ${drawLineAnimation} 1s ease-out forwards;
  }
}

${centeredContainer}
& :where(.openui-pie-chart-svg-wrapper) {
  ${centeredSvgWrapper}
}
& :where(.openui-pie-chart-track) {
  fill: var(--openui-sunk, oklch(0.097 0 0 / 0.04));
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-pie-chart-slice--animated) {
    opacity: 0;
    transform-origin: center center;
    animation: ${appear} 0.6s ease-out forwards;
  }
}

${centeredContainer}
& :where(.openui-radar-chart-svg-wrapper) {
  ${centeredSvgWrapper}
}
& svg:where(.openui-radar-chart-svg-wrapper > svg) {
  overflow: visible;
}
& :where(.openui-radar-chart-grid-ring),
& :where(.openui-radar-chart-grid-spoke) {
  stroke: var(--openui-border-interactive, oklch(0.097 0 0 / 0.12));
  stroke-width: 1;
}
& :where(.openui-radar-chart-polygon-area) {
  transition: opacity 0.2s ease;
}
& :where(.openui-radar-chart-polygon-stroke) {
  fill: none;
  stroke-width: 2;
}
& :where(.openui-radar-chart-dot) {
  stroke: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
  stroke-width: 1.5;
  transition:
    r 0.15s ease,
    opacity 0.15s ease;
}
& :where(.openui-radar-chart-active-dot-outer) {
  ${activeDotOuter}
}
& :where(.openui-radar-chart-active-dot-inner) {
  ${activeDotInner}
}
& :where(.openui-radar-chart-active-dots) {
  pointer-events: none;
}
& :where(.openui-radar-chart-axis-label) {
  ${svgTickLabel}
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-radar-chart-polygon--animated) {
    opacity: 0;
    transform-origin: center center;
    animation: ${appear} 0.5s ease-out forwards;
  }
}

${centeredContainer}
& :where(.openui-radial-chart-svg-wrapper) {
  ${centeredSvgWrapper}
}
& :where(.openui-radial-chart-grid-circle) {
  stroke: var(--openui-border-default, oklch(0.097 0 0 / 0.06));
  stroke-width: 1;
  stroke-dasharray: 4 4;
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-radial-chart-bar--animated) {
    opacity: 0;
    animation: ${fadeAppearAnimation} 0.5s ease-out forwards;
  }
}

${centeredContainer}
& line:where(.openui-scatter-chart-grid line) {
  ${gridLine}
}
& line.openui-grid-zero-line:where(.openui-scatter-chart-grid line) {
  ${zeroGridLine}
}
& line:where(.openui-scatter-chart-grid-vertical line) {
  ${gridLine}
}
& :where(.openui-scatter-chart-y-tick, .openui-scatter-chart-x-tick) {
  ${svgTickLabel}
}
& :where(.openui-scatter-chart-dot) {
  stroke: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
  stroke-width: 1.5;
  transition:
    r 0.15s ease,
    fill-opacity 0.15s ease,
    stroke-opacity 0.15s ease;
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-scatter-chart-dot--animated) {
    opacity: 0;
    animation: ${appear} 0.4s ease-out forwards;
  }
}

& {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  position: relative;
}

& {
  justify-content: center;
}
&:where(.openui-segmented-bar-container--gap) {
  gap: var(--openui-space-m, 12px);
}

& :where(.openui-segmented-bar) {
  width: 100%;
  box-sizing: border-box;
  height: 20px;
  font-family: inherit;
  background-color: var(--openui-background, oklch(0.97 0 89.876 / 1));
  border-radius: var(--openui-radius-s, 6px);
  overflow: hidden;
  box-shadow: var(
    --openui-shadow-s,
    0 1px 3px -2px oklch(0 0 0 / 0.02),
    0 2px 5px -2px oklch(0 0 0 / 0.04)
  );
  display: flex;
  padding: var(--openui-space-2xs, 4px);
  gap: var(--openui-space-3xs, 2px);
}

& :where(.openui-segmented-bar-segment) {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 2px;
  box-shadow: var(
    --openui-shadow-s,
    0 1px 3px -2px oklch(0 0 0 / 0.02),
    0 2px 5px -2px oklch(0 0 0 / 0.04)
  );
  position: relative;
  overflow: hidden;
  transition:
    box-shadow 0.2s ease,
    filter 0.2s ease,
    opacity 0.2s ease;
}
& :first-child:where(.openui-segmented-bar-segment) {
  border-radius: var(--openui-radius-xs, 4px) 0 0 var(--openui-radius-xs, 4px);
}
& :last-child:where(.openui-segmented-bar-segment) {
  border-radius: 0 var(--openui-radius-xs, 4px) var(--openui-radius-xs, 4px) 0;
}
& :where(.openui-segmented-bar-segment-line) {
  position: absolute;
  transform: translateY(-50%);
  background-color: var(--openui-border-accent-emphasis, oklch(0.546 0.215 262.881 / 0.3));
  top: 50%;
  left: 5px;
  width: calc(100% - 10px);
  height: 1px;
  z-index: 1;
  min-width: 2px;
}
& :where(.openui-segmented-bar-segment--animated) {
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

& :where(.openui-segmented-bar-stacked-legend) {
  margin-top: var(--openui-space-s, 8px);
}
